 </head>
 <body>
   <main class="card">
     <h1>Notification Settings</h1>
     <p>Select the way you would like to receive updates.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>

           <div class="radio-option">
             <label>
               <input type="radio" name="notificationPreference" value="Email" required>
               <span class="option-text">Email</span>
             </label>
           </div>

           <div class="radio-option">
             <label>
               <input type="radio" name="notificationPreference" value="SMS">
               <span class="option-text">SMS</span>
             </label>
           </div>

           <div class="radio-option">
             <label>
               <input type="radio" name="notificationPreference" value="Push Notifications">
               <span class="option-text">Push Notifications</span>
             </label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit</button>
       <div id="form-message" class="message" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const message = document.getElementById("form-message");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const selectedOption = form.querySelector('input[name="notificationPreference"]:checked');

       if (!selectedOption) {
         message.textContent = "Please choose one notification method before submitting.";
         message.classList.add("error");
         return;
       }

       message.textContent = "Preference saved: " + selectedOption.value + ".";
       message.classList.remove("error");
     });
   </script>
 </body>
